// The Gradle project that publishes the Kotlin Multiplatform module generated by
// boring (bundle kotlin-f32) as the nine org.tiqian:tiqian-engine publications.
//
// The generated tree and the publication that consumes it belong to one
// repository. The source tree is a boring output, not a hand-written one: the
// driver writes <outRoot>/<bundle>/gen and gen-tests, and the build points the
// Kotlin source sets at those directories instead of at src/. See
// engine/build.gradle.kts for the -PkotlinGenDir / -PkotlinGenTestsDir overrides.
pluginManagement {
    repositories {
        google()
        mavenCentral()
        gradlePluginPortal()
    }
}

dependencyResolutionManagement {
    repositories {
        google()
        mavenCentral()
    }
}

rootProject.name = "boring-kotlin-publication"

include(":engine")
